[TestClass]
public sealed class HealthcheckMutationPipeGuardProofTests
{
    private const string ReportSha256 = "847327cc1bb2465664ad095ed06b3b1bd26707b5a10cc15c50cc2cee81c67836";
    private const string CoreSourceSha256 = "809ba1a493d6176e354f84209ea556ae21eb726e626b35eb7cc777956cdba12f";
    private const string TestSourceSha256 = "115c483734dc6600331daa5d4d4cff43a75dcf40ae6af69c41c7c66e89ab7691";

    [TestMethod]
    [DataRow("2766", 77)]
    [DataRow("2768", 77)]
    [DataRow("2773", 70)]
    [DataRow("2777", 71)]
    public void ExactOriginalNativeRowBindsItsFrozenSourceAndFullDefinitionWithoutChangingRawStatus(string id, int expectedRows)
    {
        var fixture = new Fixture(id);
        string before = fixture.Report.ToJsonString();
        Assert.AreEqual(Observation(id).DefinitionIdentity, fixture.Definition.Identity);
        Assert.AreEqual(expectedRows, HealthcheckMutationPipeGuardCatalog.Cases.Count(review => review.Binding.Definition.Id == id));
        Assert.IsTrue(fixture.ShippingMatch(out JsonObject? witness));
        Assert.AreEqual("ReviewedPipeGuardFailure", (string?)witness!["kind"]);
        Assert.AreEqual("Killed", (string?)witness["rawStatus"]);
        Assert.AreEqual(fixture.Definition.Identity, (string?)witness["definitionIdentity"]);
        Assert.AreEqual(false, (bool?)witness["timeoutReclassified"]);
        Assert.AreEqual(false, (bool?)witness["childFailuresDischarged"]);
        Assert.AreEqual(false, (bool?)witness["wholeCampaignApproval"]);
        Assert.AreEqual(false, (bool?)witness["pdbLineEqualsOriginalSourceLineClaim"]);
        Assert.AreEqual(before, fixture.Report.ToJsonString());
    }

    [TestMethod]
    public void FixedCatalogContainsOnlyThe295ReviewedNonDirectObservationsAcrossFourOriginalDefinitions()
    {
        var cases = HealthcheckMutationPipeGuardCatalog.Cases;
        Assert.AreEqual(295, cases.Count);
        Assert.AreEqual(295, cases.Select(review => review.Binding.Definition.Id + "/" + review.Binding.Guid).Distinct(StringComparer.Ordinal).Count());
        CollectionAssert.AreEquivalent(new[] { "2766", "2768", "2773", "2777" }, cases.Select(review => review.Binding.Definition.Id).Distinct(StringComparer.Ordinal).ToArray());
        Assert.IsTrue(cases.All(review => review.Binding.ReportSha256 == ReportSha256
            && review.Binding.Definition.SourceSha256 == CoreSourceSha256
            && review.Binding.Definition.Status == "Killed"));
        Assert.IsFalse(cases.Any(review => review.Binding.Definition.Id is "2766" or "2768"
            && review.Binding.Guid is "188b3b4e-2963-879d-81f1-6c244d557c71" or "16d518f0-2d2f-860e-8ca2-e3bb828de1dd"));
    }

    [TestMethod]
    [DataRow("report")]
    [DataRow("checked-replacement")]
    [DataRow("checked-killedby-order")]
    [DataRow("raw-killedby-order")]
    [DataRow("raw-killedby-missing")]
    [DataRow("raw-replacement")]
    [DataRow("production-source")]
    [DataRow("test-source")]
    [DataRow("test-guid")]
    [DataRow("test-method")]
    [DataRow("duplicate-test-guid")]
    [DataRow("native-id")]
    [DataRow("native-guid")]
    [DataRow("native-method")]
    [DataRow("native-code-file")]
    [DataRow("explicit-start-token")]
    [DataRow("canceled-start-token")]
    public void AReviewedNativeRouteCannotApproveAnotherDefinitionOrReceivingInput(string mode)
    {
        var fixture = new Fixture("2766");
        switch (mode)
        {
            case "report": fixture.ReportHash = new string('b', 64); break;
            case "checked-replacement": fixture.Definition = fixture.Definition with { Replacement = "true" }; break;
            case "checked-killedby-order": fixture.Definition = fixture.Definition with { KilledBy = fixture.Definition.KilledBy.Reverse().ToArray() }; break;
            case "raw-killedby-order": fixture.RawDefinition["killedBy"] = new JsonArray(fixture.Definition.KilledBy.Reverse().Select(value => (JsonNode?)JsonValue.Create(value)).ToArray()); break;
            case "raw-killedby-missing": fixture.RawDefinition["killedBy"]!.AsArray().RemoveAt(0); break;
            case "raw-replacement": fixture.RawDefinition["replacement"] = "true"; break;
            case "production-source": fixture.CoreFile["source"] = OriginalCoreSource + " "; break;
            case "test-source": fixture.TestFile["source"] = OriginalTestSource + " "; break;
            case "test-guid": fixture.TestFile["tests"]![0]!["id"] = OtherGuid; break;
            case "test-method": fixture.TestFile["tests"]![0]!["name"] = Fixture.Method + "Other"; break;
            case "duplicate-test-guid": fixture.TestFile["tests"]!.AsArray().Add(fixture.TestFile["tests"]![0]!.DeepClone()); break;
            case "native-id": fixture.MutantId = "2767"; break;
            case "native-guid": fixture.NativeGuid = OtherGuid; break;
            case "native-method": fixture.NativeMethod += "Other"; break;
            case "native-code-file": fixture.CodeFile += ".other"; break;
            case "explicit-start-token": fixture.TestFile["source"] = OriginalTestSource.Replace("server.StartAsync()", "server.StartAsync(CancellationToken.None)", StringComparison.Ordinal); break;
            case "canceled-start-token": fixture.TestFile["source"] = OriginalTestSource.Replace("server.StartAsync()", "server.StartAsync(canceled.Token)", StringComparison.Ordinal); break;
            default: throw new InvalidOperationException("Unknown exact binding control.");
        }
        Assert.IsFalse(fixture.ShippingMatch(out JsonObject? witness));
        Assert.IsNull(witness);
    }

    [TestMethod]
    [DataRow("message-byte")]
    [DataRow("message-line-ending")]
    [DataRow("stack-byte")]
    [DataRow("stack-line-ending")]
    [DataRow("unknown-exception")]
    public void UnknownMessageOrStackBytesCannotEnterTheFixedCatalog(string mode)
    {
        var fixture = new Fixture("2766");
        switch (mode)
        {
            case "message-byte": fixture.Message += " "; break;
            case "message-line-ending": fixture.Message = fixture.Message.Replace("\r\n", "\n", StringComparison.Ordinal); break;
            case "stack-byte": fixture.Stack += "\n"; break;
            case "stack-line-ending": fixture.Stack = fixture.Stack.Replace("\n", "\r\n", StringComparison.Ordinal); break;
            case "unknown-exception": fixture.Message = fixture.Message.Replace("System.ArgumentException:", "System.NullReferenceException:", StringComparison.Ordinal); break;
            default: throw new InvalidOperationException("Unknown raw observation control.");
        }
        Assert.IsFalse(fixture.ShippingMatch(out JsonObject? witness));
        Assert.IsNull(witness);
    }

    [TestMethod]
    [DataRow("2766", "wrong-core-method")]
    [DataRow("2766", "wrong-core-file")]
    [DataRow("2766", "prepend-library-frame")]
    [DataRow("2773", "wrong-bcl-first-frame")]
    [DataRow("2773", "missing-bcl-first-frame")]
    [DataRow("2766", "wrong-receiving-method")]
    [DataRow("2766", "wrong-receiving-line")]
    [DataRow("2766", "wrong-adapter-terminal")]
    [DataRow("2766", "cleanup")]
    [DataRow("2766", "initialize")]
    [DataRow("2766", "deadline")]
    [DataRow("2766", "cancellation")]
    [DataRow("2766", "aggregate")]
    [DataRow("2766", "unknown-guard")]
    [DataRow("2766", "missing-contract")]
    [DataRow("2766", "missing-input")]
    [DataRow("2766", "missing-cause")]
    [DataRow("2766", "bad-message-pin")]
    [DataRow("2766", "bad-stack-pin")]
    public void EvenARepinnedTypedReceivingInputMustRetainItsReviewedFirstOriginAndContract(string id, string mode)
    {
        var fixture = new Fixture(id);
        switch (mode)
        {
            case "wrong-core-method": fixture.Stack = fixture.Stack.Replace("HealthPipeServer..ctor(", "HealthPipeServer.Other(", StringComparison.Ordinal); break;
            case "wrong-core-file": fixture.Stack = fixture.Stack.Replace(Fixture.CorePath, Fixture.CorePath + ".other", StringComparison.Ordinal); break;
            case "prepend-library-frame": fixture.Stack = "   at System.IO.Stream.Unrelated()\n" + fixture.Stack; break;
            case "wrong-bcl-first-frame": fixture.Stack = fixture.Stack.Replace("Task.FromCanceled(", "Task.Unrelated(", StringComparison.Ordinal); break;
            case "missing-bcl-first-frame": fixture.Stack = string.Join('\n', fixture.Stack.Split('\n').Skip(1)); break;
            case "wrong-receiving-method": fixture.Stack = fixture.Stack.Replace(Fixture.Method + "(", Fixture.Method + "Other(", StringComparison.Ordinal); break;
            case "wrong-receiving-line": fixture.Review = fixture.Review with { ReceivingLine = fixture.Review.ReceivingLine + 1 }; break;
            case "wrong-adapter-terminal": fixture.Stack = fixture.Stack.Replace("TestMethodInfo.ExecuteInternalAsync", "Unrelated.Execute", StringComparison.Ordinal); break;
            case "cleanup": fixture.InsertFrame("Fixture.DisposeAsync()"); break;
            case "initialize": fixture.InsertFrame("Fixture.TestInitialize()"); break;
            case "deadline": fixture.InsertFrame("System.TimeoutException.Guard()"); break;
            case "cancellation": fixture.InsertFrame("Fixture.OperationCanceledException()"); break;
            case "aggregate": fixture.InsertFrame("Fixture.AggregateException()"); break;
            case "unknown-guard": fixture.Review = fixture.Review with { Guard = (Proofs.GuardKind)int.MaxValue }; break;
            case "missing-contract": fixture.Review = fixture.Review with { ContractReview = "" }; break;
            case "missing-input": fixture.Review = fixture.Review with { AdmittedInputReview = "" }; break;
            case "missing-cause": fixture.Review = fixture.Review with { CausalReview = "" }; break;
            case "bad-message-pin": break;
            case "bad-stack-pin": break;
            default: throw new InvalidOperationException("Unknown reviewed route control.");
        }
        fixture.Review = fixture.Review with { NativeMessageSha256 = Hash(fixture.Message), NativeStackSha256 = Hash(fixture.Stack) };
        if (mode == "bad-message-pin") { fixture.Review = fixture.Review with { NativeMessageSha256 = "unknown" }; }
        if (mode == "bad-stack-pin") { fixture.Review = fixture.Review with { NativeStackSha256 = "unknown" }; }
        Assert.IsFalse(fixture.TypedMatch(out JsonObject? witness));
        Assert.IsNull(witness);
    }

    [TestMethod]
    public void AnExplicitTypedParserReviewCannotBecomeAnImplicitCatalogApproval()
    {
        var fixture = new Fixture("2766") { ReportHash = new string('a', 64) };
        fixture.Review = fixture.Review with { Binding = fixture.Review.Binding with { ReportSha256 = fixture.ReportHash } };
        Assert.IsTrue(fixture.TypedMatch(out _));
        Assert.IsFalse(fixture.ShippingMatch(out _));
    }

    private const string OtherGuid = "22222222-2222-4222-8222-222222222222";
    private sealed record ActualRow(string DefinitionIdentity, string RawDefinition, string Message, string Stack);

    private sealed class Fixture
    {
        private const string NativeRoot = "/data/cis-healthcheck-20261021-01a15a72/pipes-full-20/source";
        internal const string CorePath = NativeRoot + "/implementations/csharp/src/CIS.Core/Healthcheck/Pipes/HealthPipeServer.cs";
        internal const string TestPath = "implementations/csharp/tests/CIS.Core.UnitTests/Healthcheck/Reporting/HealthPipeInternalMutationQualificationTests.cs";
        internal const string Method = "CIS.Tests.UnitTests.Healthcheck.HealthPipeInternalMutationQualificationTests.FailedStandardOutputIsReportedAsTransportFailureWithoutLeakingTheException";
        private const string Guid = "12195f68-1cc1-8ccc-9c48-0672e31d1faa";
        internal string MutantId { get; set; }
        internal string NativeGuid { get; set; } = Guid;
        internal string NativeMethod { get; set; } = Method;
        internal string CodeFile { get; set; } = NativeRoot + "/" + TestPath;
        internal string ReportHash { get; set; } = ReportSha256;
        internal string Message { get; set; }
        internal string Stack { get; set; }
        internal Definition Definition { get; set; }
        internal Proofs.ReviewedCase Review { get; set; }
        internal JsonObject Report { get; }
        internal JsonObject CoreFile => Report["files"]![CorePath]!.AsObject();
        internal JsonObject RawDefinition => CoreFile["mutants"]![0]!.AsObject();
        internal JsonObject TestFile => Report["testFiles"]![NativeRoot + "/" + TestPath]!.AsObject();

        internal Fixture(string id)
        {
            ActualRow row = Observation(id);
            Assert.AreEqual(CoreSourceSha256, Hash(OriginalCoreSource));
            Assert.AreEqual(TestSourceSha256, Hash(OriginalTestSource));
            JsonObject raw = JsonNode.Parse(row.RawDefinition)!.AsObject();
            (int start, int end) = id switch { "2766" or "2768" => (1583, 1612), "2773" => (2096, 2136), "2777" => (2293, 2301), _ => throw new InvalidOperationException("Unknown original definition.") };
            Definition = new(id, "Healthcheck/Pipes/HealthPipeServer.cs", CoreSourceSha256, start, end,
                raw["mutatorName"]!.GetValue<string>(), OriginalCoreSource[start..end], raw["replacement"]!.GetValue<string>(), "Killed",
                raw["killedBy"]!.AsArray().Select(value => value!.GetValue<string>()).ToArray());
            MutantId = id; Message = row.Message; Stack = row.Stack;
            Review = HealthcheckMutationPipeGuardCatalog.Cases.Single(review => review.Binding.Definition.Id == id && review.Binding.Guid == Guid);
            Report = new JsonObject
            {
                ["files"] = new JsonObject { [CorePath] = new JsonObject { ["source"] = OriginalCoreSource, ["mutants"] = new JsonArray(raw) } },
                ["testFiles"] = new JsonObject
                {
                    [NativeRoot + "/" + TestPath] = new JsonObject
                    {
                        ["source"] = OriginalTestSource,
                        ["tests"] = new JsonArray(new JsonObject { ["id"] = Guid, ["name"] = Method })
                    }
                }
            };
        }

        internal Semantics.Context Context() => new(ReportHash, [Definition], Report);
        internal bool ShippingMatch(out JsonObject? witness) => Proofs.TryMatch(Context(), MutantId, NativeGuid, NativeMethod, CodeFile, Message, Stack, out witness);
        internal bool TypedMatch(out JsonObject? witness) => Proofs.MatchReviewedCase(Review, Context(), MutantId, NativeGuid, NativeMethod, CodeFile, Message, Stack, out witness);
        internal void InsertFrame(string frame)
        {
            const string terminal = "   at Microsoft.VisualStudio.TestPlatform.MSTest.TestAdapter.Execution.TestMethodInfo.ExecuteInternalAsync";
            Stack = Stack.Replace(terminal, "   at " + frame + "\n" + terminal, StringComparison.Ordinal);
        }
    }

    private static string Hash(string value) => Convert.ToHexStringLower(SHA256.HashData(new UTF8Encoding(false, true).GetBytes(value)));

